SELECT "qast_order"."id", "qast_order"."name", "qast_order"."date" FROM "qast_order" WHERE ("qast_order"."active" IS TRUE AND "qast_order"."date" <= (now() AT TIME ZONE 'UTC')::date) AND (("qast_order"."company_id" IS NULL OR "qast_order"."company_id" = ANY($1::int8[])) AND "qast_order"."user_id" = $2::int8) ORDER BY "qast_order"."date" ASC NULLS LAST, "qast_order"."id" LIMIT $3::int8 OFFSET $4::int8
-- parameters: 4
